#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Threading;
using System.Threading.Tasks;
using System.Xml.Linq;
using Microsoft.AspNetCore.OpenApi;
using Microsoft.OpenApi;

namespace TransactionProcessor.OpenApi;

/// <summary>
/// Adds DTO XML comments and examples to the OpenAPI document generated by ApiDefaults.
/// </summary>
public sealed class DtoDocumentationTransformer : IOpenApiDocumentTransformer
{
    private const string DocumentationFileName = "TransactionProcessor.DataTransferObjects.xml";

    /// <inheritdoc />
    public Task TransformAsync(OpenApiDocument document,
                               OpenApiDocumentTransformerContext context,
                               CancellationToken cancellationToken)
    {
        string documentationPath = Path.Combine(AppContext.BaseDirectory, DocumentationFileName);
        if (!File.Exists(documentationPath))
        {
            return Task.CompletedTask;
        }

        Dictionary<string, XElement> members = XDocument.Load(documentationPath)
                                                         .Root?
                                                         .Element("members")?
                                                         .Elements("member")
                                                         .Where(member => member.Attribute("name") is not null)
                                                         .ToDictionary(member => member.Attribute("name")!.Value,
                                                                       member => member,
                                                                       StringComparer.Ordinal)
            ?? new Dictionary<string, XElement>(StringComparer.Ordinal);

        IDictionary<string, IOpenApiSchema> componentSchemas = document.Components?.Schemas ??
            new Dictionary<string, IOpenApiSchema>(StringComparer.Ordinal);
        foreach (KeyValuePair<string, IOpenApiSchema> schemaEntry in componentSchemas)
        {
            if (schemaEntry.Value is not OpenApiSchema schema)
            {
                continue;
            }

            schema.Properties ??= new Dictionary<string, IOpenApiSchema>(StringComparer.Ordinal);
            if (string.Equals(schemaEntry.Key, "ProblemDetails", StringComparison.Ordinal))
            {
                schema.Description ??= "RFC 9457 problem details returned when a request fails.";
                schema.Examples ??= new List<JsonNode>();
                if (schema.Examples.Count == 0 && ReadExample("""{"type":"about:blank","title":"An error occurred.","detail":"The request could not be completed."}""") is JsonNode problemExample)
                {
                    schema.Examples.Add(problemExample);
                }

                AddProblemDetailsPropertyDescriptions(schema);
            }

            string? typeMemberName = FindTypeMember(schemaEntry.Key, schema, members);
            if (typeMemberName is null)
            {
                continue;
            }

            XElement typeMember = members[typeMemberName];
            schema.Description ??= ReadDocumentationText(typeMember.Element("summary"));
            schema.Examples ??= new List<JsonNode>();
            if (schema.Examples.Count == 0 && ReadExample(typeMember.Element("example")) is JsonNode example)
            {
                schema.Examples.Add(NormalizeExample(example, schema));
            }

            foreach (string documentedTypeMemberName in GetTypeMemberHierarchy(typeMemberName, members))
            {
                string memberPrefix = $"P:{documentedTypeMemberName[2..]}.";
                foreach (KeyValuePair<string, IOpenApiSchema> propertyEntry in schema.Properties.ToArray())
                {
                    string propertyName = ToPascalCase(propertyEntry.Key);
                    if (members.TryGetValue(memberPrefix + propertyName, out XElement? propertyMember))
                    {
                        schema.Properties[propertyEntry.Key] = WithDescription(
                            propertyEntry.Value,
                            ReadDocumentationText(propertyMember.Element("summary")));
                    }
                }
            }

        }

        foreach (KeyValuePair<string, IOpenApiPathItem> pathEntry in document.Paths ??
                 new Dictionary<string, IOpenApiPathItem>(StringComparer.Ordinal))
        {
            IOpenApiPathItem path = pathEntry.Value;
            foreach (OpenApiOperation operation in path.Operations?.Values ?? Enumerable.Empty<OpenApiOperation>())
            {
                AddPathParameterDescriptions(pathEntry.Key, operation);

                if (operation.RequestBody is OpenApiRequestBody requestBody)
                {
                    foreach (OpenApiMediaType mediaType in requestBody.Content?.Values ?? Enumerable.Empty<OpenApiMediaType>())
                    {
                        mediaType.Example ??= GetExample(mediaType.Schema);
                    }
                }

                foreach (IOpenApiResponse response in operation.Responses?.Values ?? Enumerable.Empty<IOpenApiResponse>())
                {
                    foreach (OpenApiMediaType mediaType in response.Content?.Values ?? Enumerable.Empty<OpenApiMediaType>())
                    {
                        mediaType.Example ??= GetExample(mediaType.Schema);
                    }
                }
            }
        }

        AddDomainEventExample(document);

        return Task.CompletedTask;
    }

    private static void AddPathParameterDescriptions(string route, OpenApiOperation operation)
    {
        foreach (IOpenApiParameter parameter in operation.Parameters ?? Enumerable.Empty<IOpenApiParameter>())
        {
            if (parameter.In != ParameterLocation.Path)
            {
                continue;
            }

            string? description = parameter.Name switch
            {
                "estateId" => "Unique identifier of the estate that owns or scopes this resource.",
                "merchantId" => "Unique identifier of the merchant within the specified estate.",
                "operatorId" => "Unique identifier of the operator associated with the estate or merchant.",
                "contractId" => "Unique identifier of the contract within the specified estate or merchant.",
                "productId" => "Unique identifier of the product on the specified contract.",
                "transactionFeeId" => "Unique identifier of the transaction fee to disable.",
                "deviceIdentifier" => "Identifier of the merchant device to replace.",
                "addressId" => "Unique identifier of the merchant address to update.",
                "contactId" => "Unique identifier of the merchant contact to update.",
                "year" => "Calendar year for the merchant schedule.",
                "settlementDate" => "Settlement date, supplied as a date value (for example, 2026-01-15).",
                "settlementId" => "Unique identifier of the settlement.",
                "transactionId" => "Unique identifier of the transaction whose receipt is being resent.",
                _ => null
            };

            if (description is not null)
            {
                // Parameter XML docs are shared by both receipt routes; use the route context
                // so the legacy route's estateId is documented as a path value.
                parameter.Description = parameter.Name == "estateId" &&
                                        route.Equals("/api/{estateId}/transactions/{transactionId}/resendreceipt", StringComparison.Ordinal)
                    ? "Unique identifier of the estate that owns the transaction."
                    : description;
            }
        }
    }

    private static void AddDomainEventExample(OpenApiDocument document)
    {
        string documentationPath = Path.Combine(AppContext.BaseDirectory, "TransactionProcessor.xml");
        if (!File.Exists(documentationPath) ||
            document.Paths is null ||
            !document.Paths.TryGetValue("/api/domainevents", out IOpenApiPathItem? path) ||
            path.Operations is null ||
            !path.Operations.TryGetValue(System.Net.Http.HttpMethod.Post, out OpenApiOperation? operation) ||
            operation.RequestBody is not OpenApiRequestBody requestBody)
        {
            return;
        }

        XElement? parameterDocumentation = XDocument.Load(documentationPath)
                                                     .Root?
                                                     .Element("members")?
                                                     .Elements("member")
                                                     .Where(member => member.Attribute("name")?.Value.StartsWith(
                                                         "M:TransactionProcessor.Controllers.DomainEventController.PostEventAsync(",
                                                         StringComparison.Ordinal) == true)
                                                     .SelectMany(member => member.Elements("param"))
                                                     .FirstOrDefault(parameter => parameter.Attribute("name")?.Value == "request");
        string? example = parameterDocumentation?.Attribute("example")?.Value;
        if (string.IsNullOrWhiteSpace(example))
        {
            return;
        }

        JsonNode? parsedExample = ReadExample(example);
        foreach (OpenApiMediaType mediaType in requestBody.Content?.Values ?? Enumerable.Empty<OpenApiMediaType>())
        {
            mediaType.Example ??= parsedExample?.DeepClone();
        }
    }

    private static string? FindTypeMember(string schemaName,
                                          OpenApiSchema schema,
                                          IReadOnlyDictionary<string, XElement> members)
    {
        string[] candidates = members.Keys.Where(name => name.StartsWith("T:", StringComparison.Ordinal) &&
                                                          name.EndsWith($".{schemaName}", StringComparison.Ordinal))
                                          .ToArray();
        if (candidates.Length == 0)
        {
            return null;
        }

        IDictionary<string, IOpenApiSchema> properties = schema.Properties ??
            new Dictionary<string, IOpenApiSchema>(StringComparer.Ordinal);

        return candidates.OrderByDescending(candidate =>
        {
            string prefix = $"P:{candidate[2..]}.";
            return properties.Keys.Count(propertyName =>
                members.ContainsKey(prefix + ToPascalCase(propertyName)));
        }).First();
    }

    private static JsonNode? GetExample(IOpenApiSchema? openApiSchema)
    {
        if (openApiSchema is OpenApiSchemaReference reference)
        {
            return GetExample(reference.Target);
        }

        if (openApiSchema is not OpenApiSchema schema)
        {
            return null;
        }

        if (schema.Examples?.FirstOrDefault() is JsonNode example)
        {
            return example.DeepClone();
        }

        if (schema.Items is not null && GetExample(schema.Items) is JsonNode itemExample)
        {
            return new JsonArray(itemExample);
        }

        return null;
    }

    private static JsonNode NormalizeExample(JsonNode example, IOpenApiSchema schema)
    {
        if (schema is OpenApiSchemaReference reference)
        {
            return NormalizeExample(example, reference.Target);
        }

        if (schema is not OpenApiSchema openApiSchema)
        {
            return example.DeepClone();
        }

        IDictionary<string, IOpenApiSchema> properties = openApiSchema.Properties ??
            new Dictionary<string, IOpenApiSchema>(StringComparer.Ordinal);
        if (example is JsonObject exampleObject && properties.Count > 0)
        {
            JsonObject normalizedObject = new();
            foreach (KeyValuePair<string, JsonNode?> property in exampleObject)
            {
                string schemaPropertyName = properties.Keys.FirstOrDefault(name =>
                    string.Equals(ToPascalCase(name), ToPascalCase(property.Key), StringComparison.OrdinalIgnoreCase))
                    ?? property.Key;
                JsonNode? value = property.Value;
                normalizedObject[schemaPropertyName] = value is not null &&
                                                       properties.TryGetValue(schemaPropertyName,
                                                           out IOpenApiSchema? propertySchema)
                    ? NormalizeExample(value, propertySchema)
                    : value?.DeepClone();
            }

            return normalizedObject;
        }

        IOpenApiSchema? itemsSchema = openApiSchema.Items;
        if (example is JsonArray exampleArray && itemsSchema is not null)
        {
            JsonArray normalizedArray = new();
            foreach (JsonNode? item in exampleArray)
            {
                normalizedArray.Add(item is null ? null : NormalizeExample(item, itemsSchema));
            }

            return normalizedArray;
        }

        return example.DeepClone();
    }

    private static IEnumerable<string> GetTypeMemberHierarchy(string typeMemberName,
                                                               IReadOnlyDictionary<string, XElement> members)
    {
        yield return typeMemberName;

        string typeName = typeMemberName[2..];
        Assembly? dtoAssembly = AppDomain.CurrentDomain.GetAssemblies()
                                                       .FirstOrDefault(assembly => string.Equals(
                                                           assembly.GetName().Name,
                                                           "TransactionProcessor.DataTransferObjects",
                                                           StringComparison.Ordinal));
        Type? dtoType = dtoAssembly?.GetType(typeName, throwOnError: false);
        for (Type? baseType = dtoType?.BaseType;
             baseType is not null && baseType != typeof(object);
             baseType = baseType.BaseType)
        {
            string baseTypeMemberName = $"T:{baseType.FullName}";
            if (members.ContainsKey(baseTypeMemberName))
            {
                yield return baseTypeMemberName;
            }
        }
    }

    private static IOpenApiSchema WithDescription(IOpenApiSchema schema, string? description)
    {
        if (string.IsNullOrWhiteSpace(description))
        {
            return schema;
        }

        if (schema is OpenApiSchema openApiSchema)
        {
            openApiSchema.Description ??= description;
            return openApiSchema;
        }

        // OpenAPI serializes schema references without sibling descriptions. Wrap the reference
        // in allOf so property documentation remains visible to clients such as Scalar.
        return schema is OpenApiSchemaReference
            ? new OpenApiSchema
            {
                Description = description,
                AllOf = new List<IOpenApiSchema> { schema }
            }
            : schema;
    }

    private static void AddProblemDetailsPropertyDescriptions(OpenApiSchema schema)
    {
        (string Name, string Description)[] descriptions =
        [
            ("type", "URI reference identifying the problem type. Defaults to about:blank."),
            ("title", "Short, human-readable summary of the problem."),
            ("status", "HTTP status code for this occurrence of the problem."),
            ("detail", "Human-readable explanation specific to this occurrence."),
            ("instance", "URI reference identifying this specific occurrence of the problem.")
        ];

        foreach ((string name, string description) in descriptions)
        {
            if (schema.Properties.TryGetValue(name, out IOpenApiSchema? propertySchema))
            {
                schema.Properties[name] = WithDescription(propertySchema, description);
            }
        }
    }

    private static JsonNode? ReadExample(XElement? exampleElement)
    {
        return ReadExample(exampleElement?.Value);
    }

    private static JsonNode? ReadExample(string? example)
    {
        string? value = example?.Trim();
        if (string.IsNullOrEmpty(value))
        {
            return null;
        }

        try
        {
            return JsonNode.Parse(value);
        }
        catch (JsonException)
        {
            return JsonValue.Create(value);
        }
    }

    private static string? ReadDocumentationText(XElement? element)
    {
        string value = string.Join(" ", element?.Value.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries) ?? []);
        return string.IsNullOrWhiteSpace(value) ? null : value;
    }

    private static string ToPascalCase(string value) =>
        string.Concat(value.Split('_', StringSplitOptions.RemoveEmptyEntries)
                           .Select(part => char.ToUpperInvariant(part[0]) + part[1..]));
}
